// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  Img,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBebas = makeLoadFont('BebasNeue');
const loadInter = makeLoadFont('Inter');
const loadMontserrat = makeLoadFont('Montserrat');
const loadOswald = makeLoadFont('Oswald');

const { fontFamily: bebasFamily } = loadBebas();
const { fontFamily: interFamily } = loadInter();
const { fontFamily: montserratFamily } = loadMontserrat();
const { fontFamily: oswaldFamily } = loadOswald();

const getFontFamily = (fontName: string) => {
  switch (fontName) {
    case "Inter":
      return interFamily;
    case "Montserrat":
      return montserratFamily;
    case "Oswald":
      return oswaldFamily;
    case "Bebas Neue":
    default:
      return bebasFamily;
  }
};



export type LuxuryVillaCarouselProps = Record<string, any>;

const LuxuryVillaCarousel: React.FC<LuxuryVillaCarouselProps> = ({
  backgroundColor = "#ff3f92",
  transparentBackground = false,
  durationInSeconds = 15,
  villaImages = [
    "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/5846e24c7cbd44caaab6db22113f3055.png",
    "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/6ad6bf7237d946918094231c26849b27.png",
    "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/849eb30929b845c4837d2b4cc016c601.png",
    "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/ff1941e1fa5c490a8021e0a14b5a52dc.png",
    "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/4c2cf8731d284d5b88d5dd8952b90832.png",
    "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/67906f27ae8c412da8178960354de3ef.png",
  ],
  cardWidth = 380,
  cardHeight = 680,
  carouselRadius = 380,
  rotationSpeed = 0.5,
  cardBorderRadius = 24,
  shadowIntensity = 0.6,
  blurStrength = 4,
  logoImage = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/e56d215b313c4517a5dc806bdbbd2a84.png",
  logoWidth = 240,
  logoScale = 1.0,
  saleTitle = "GYMSHARK SALE",
  saleSubtitle = "UP TO 60% OFF EVERYTHING",
  saleFontColor = "#ffffff",
  saleFontFamily = "Bebas Neue",
  saleTitleFontSize = 130,
  saleSubtitleFontSize = 60,
  salePositionBottomPercent = 8,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background Logic
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Global rotation of the carousel over time
  const globalRotation = interpolate(
    frame,
    [0, durationInSeconds * fps],
    [0, 360 * rotationSpeed]
  );

  const count = villaImages.length;
  const angleStep = 360 / count;

  // Text Entrance Animation
  const textEntrance = spring({
    frame: frame - 10,
    fps,
    config: {
      damping: 12,
      stiffness: 100,
      mass: 0.8,
    },
  });

  const textY = interpolate(textEntrance, [0, 1], [40, 0]);
  const textOpacity = interpolate(textEntrance, [0, 1], [0, 1]);

  const selectedFontFamily = getFontFamily(saleFontFamily);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        perspective: "1200px",
        overflow: "hidden",
      }}
    >
      {/* Logo at the top */}
      <div
        style={{
          position: "absolute",
          top: height * 0.08,
          left: 0,
          right: 0,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 100,
          transform: `scale(${logoScale})`,
        }}
      >
        <Img
          src={logoImage}
          style={{
            width: logoWidth,
            height: "auto",
            objectFit: "contain",
          }}
        />
      </div>

      <div
        style={{
          width: width,
          height: height,
          position: "relative",
          transformStyle: "preserve-3d",
        }}
      >
        {villaImages.map((src, index) => {
          const baseAngle = index * angleStep;
          const currentAngle = baseAngle - globalRotation;
          const normalizedAngle = ((currentAngle % 360) + 360) % 360;
          const distanceToFront = Math.min(
            Math.abs(normalizedAngle - 0),
            Math.abs(normalizedAngle - 360)
          );

          const blurAmount = interpolate(
            distanceToFront,
            [0, 90, 180],
            [0, blurStrength, blurStrength * 2],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          const opacity = 1;

          const depthScale = interpolate(
            distanceToFront,
            [0, 180],
            [1, 0.8],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          const staggerDelay = 8;
          const startFrame = index * staggerDelay;
          
          const popUpScale = spring({
            frame: frame - startFrame,
            fps,
            config: {
              damping: 12,
              stiffness: 100,
              mass: 0.8,
            },
          });

          const finalScale = depthScale * popUpScale;

          const shadowOpacity = interpolate(
             distanceToFront,
             [0, 180],
             [shadowIntensity, 0]
          );
          
          return (
            <div
              key={index}
              style={{
                position: "absolute",
                width: cardWidth,
                height: cardHeight,
                left: (width - cardWidth) / 2,
                top: (height - cardHeight) / 2 - 60, // Shifted slightly up to give more room for text below
                transformStyle: "preserve-3d",
                transform: `
                  rotateY(${baseAngle - globalRotation}deg) 
                  translateZ(${carouselRadius}px) 
                  scale(${finalScale})
                `,
                borderRadius: cardBorderRadius,
                zIndex: Math.round((180 - distanceToFront) * 10), 
              }}
            >
              <div
                style={{
                  width: "100%",
                  height: "100%",
                  borderRadius: cardBorderRadius,
                  overflow: "hidden",
                  backgroundColor: "#000",
                  boxShadow: `0px 20px 40px rgba(0,0,0,${shadowOpacity})`,
                  filter: `blur(${blurAmount}px)`,
                  opacity: opacity,
                  border: "1px solid rgba(255,255,255,0.1)",
                }}
              >
                <Img
                  src={src}
                  style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "cover",
                  }}
                />
              </div>
              
              <div
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  width: "100%",
                  height: "100%",
                  borderRadius: cardBorderRadius,
                  background: "linear-gradient(135deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0) 50%)",
                  pointerEvents: "none",
                  opacity: interpolate(distanceToFront, [0, 90], [1, 0]),
                }}
              />
            </div>
          );
        })}
      </div>

      {/* Gymshark Text Banner Below Carousels */}
      <div
        style={{
          position: "absolute",
          bottom: height * (salePositionBottomPercent / 100),
          left: 0,
          right: 0,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          textAlign: "center",
          padding: "0 40px",
          fontFamily: selectedFontFamily,
          color: saleFontColor,
          zIndex: 150,
          opacity: textOpacity,
          transform: `translateY(${textY}px)`,
          pointerEvents: "none",
        }}
      >
        <div
          style={{
            fontSize: saleTitleFontSize,
            fontWeight: "900",
            lineHeight: 0.9,
            letterSpacing: "0.5px",
            textTransform: "uppercase",
            margin: 0,
            padding: 0,
          }}
        >
          {saleTitle}
        </div>
        <div
          style={{
            fontSize: saleSubtitleFontSize,
            fontWeight: "900",
            lineHeight: 0.9,
            letterSpacing: "0.2px",
            textTransform: "uppercase",
            marginTop: 8,
            marginLeft: 0,
            marginRight: 0,
            padding: 0,
          }}
        >
          {saleSubtitle}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default LuxuryVillaCarousel;